    Timer_t * pxTimer = xTimer;

    traceENTER_xTimerIsTimerActive( xTimer );

    configASSERT( xTimer );

    /* Is the timer in the list of active timers? */
    portBASE_TYPE_ENTER_CRITICAL();
    {
        if( ( pxTimer->ucStatus & tmrSTATUS_IS_ACTIVE ) == 0U )
        {
            xReturn = pdFALSE;
