    traceENTER_xQueueCreateMutex( ucQueueType );

    xNewQueue = xQueueGenericCreate( uxMutexLength, uxMutexSize, ucQueueType );
    prvInitialiseMutex( ( Queue_t * ) xNewQueue );

    traceRETURN_xQueueCreateMutex( xNewQueue );

