     * configUSE_TRACE_FACILITY does not equal 1. */
    ( void ) ucQueueType;

    xNewQueue = xQueueGenericCreateStatic( uxMutexLength, uxMutexSize, NULL, pxStaticQueue, ucQueueType );
    prvInitialiseMutex( ( Queue_t * ) xNewQueue );

