void vQueueUnregisterQueue( QueueHandle_t xQueue )
{
    UBaseType_t ux;

    traceENTER_vQueueUnregisterQueue( xQueue );

    configASSERT( xQueue );

    /* See if the handle of the queue being unregistered in actually in the
     * registry. */
    for( ux = ( UBaseType_t ) 0U; ux < ( UBaseType_t ) configQUEUE_REGISTRY_SIZE; ux++ )
    {
        if( xQueueRegistry[ ux ].xHandle == xQueue )
        {
            /* Set the name to NULL to show that this slot if free again. */
            xQueueRegistry[ ux ].pcQueueName = NULL;

            /* Set the handle to NULL to ensure the same queue handle cannot
             * appear in the registry twice if it is added, removed, then
             * added again. */
            xQueueRegistry[ ux ].xHandle = ( QueueHandle_t ) 0;
            break;
        }
        else
        {
            mtCOVERAGE_TEST_MARKER();
        }
    }

    traceRETURN_vQueueUnregisterQueue();
}

void vQueueWaitForMessageRestricted( QueueHandle_t xQueue,
                                     TickType_t xTicksToWait,
                                     const BaseType_t xWaitIndefinitely )
{
    Queue_t * const pxQueue = xQueue;

    traceENTER_vQueueWaitForMessageRestricted( xQueue, xTicksToWait, xWaitIndefinitely );

    /* This function should not be called by application code hence the
     * 'Restricted' in its name.  It is not part of the public API.  It is
     * designed for use by kernel code, and has special calling requirements.
     * It can result in vListInsert() being called on a list that can only
     * possibly ever have one item in it, so the list will be fast, but even
     * so it should be called with the scheduler locked and not from a critical
     * section. */

    /* Only do anything if there are no messages in the queue.  This function
     *  will not actually cause the task to block, just place it on a blocked
     *  list.  It will not block until the scheduler is unlocked - at which
     *  time a yield will be performed.  If an item is added to the queue while
     *  the queue is locked, and the calling task blocks on the queue, then the
     *  calling task will be immediately unblocked when the queue is unlocked. */
    prvLockQueue( pxQueue );

    if( pxQueue->uxMessagesWaiting == ( UBaseType_t ) 0U )
    {
        /* There is nothing in the queue, block for the specified period. */
        vTaskPlaceOnEventListRestricted( &( pxQueue->xTasksWaitingToReceive ), xTicksToWait, xWaitIndefinitely );
    }
    else
    {
        mtCOVERAGE_TEST_MARKER();
    }

    prvUnlockQueue( pxQueue );

    traceRETURN_vQueueWaitForMessageRestricted();
}

static TCB_t * prvCreateStaticTask( TaskFunction_t pxTaskCode,
                                    const char * const pcName,
                                    const configSTACK_DEPTH_TYPE uxStackDepth,
                                    void * const pvParameters,
                                    UBaseType_t uxPriority,
                                    StackType_t * const puxStackBuffer,
                                    StaticTask_t * const pxTaskBuffer,
                                    TaskHandle_t * const pxCreatedTask )
{
    TCB_t * pxNewTCB;

    configASSERT( puxStackBuffer != NULL );
    configASSERT( pxTaskBuffer != NULL );

    #if ( configASSERT_DEFINED == 1 )
    {
        /* Sanity check that the size of the structure used to declare a
         * variable of type StaticTask_t equals the size of the real task
         * structure. */
        volatile size_t xSize = sizeof( StaticTask_t );
        configASSERT( xSize == sizeof( TCB_t ) );
        ( void ) xSize; /* Prevent unused variable warning when configASSERT() is not used. */
    }
    #endif /* configASSERT_DEFINED */

    if( ( pxTaskBuffer != NULL ) && ( puxStackBuffer != NULL ) )
    {
        /* The memory used for the task's TCB and stack are passed into this
         * function - use them. */
        /* MISRA Ref 11.3.1 [Misaligned access] */
        /* More details at: https://github.com/FreeRTOS/FreeRTOS-Kernel/blob/main/MISRA.md#rule-113 */
        /* coverity[misra_c_2012_rule_11_3_violation] */
        pxNewTCB = ( TCB_t * ) pxTaskBuffer;
        ( void ) memset( ( void * ) pxNewTCB, 0x00, sizeof( TCB_t ) );
        pxNewTCB->pxStack = ( StackType_t * ) puxStackBuffer;

        #if ( tskSTATIC_AND_DYNAMIC_ALLOCATION_POSSIBLE != 0 )
        {
            /* Tasks can be created statically or dynamically, so note this
             * task was created statically in case the task is later deleted. */
            pxNewTCB->ucStaticallyAllocated = tskSTATICALLY_ALLOCATED_STACK_AND_TCB;
        }
        #endif /* tskSTATIC_AND_DYNAMIC_ALLOCATION_POSSIBLE */

        prvInitialiseNewTask( pxTaskCode, pcName, uxStackDepth, pvParameters, uxPriority, pxCreatedTask, pxNewTCB, NULL );
    }
    else
    {
        pxNewTCB = NULL;
    }

    return pxNewTCB;
}

TaskHandle_t xTaskCreateStatic( TaskFunction_t pxTaskCode,
                                const char * const pcName,
                                const configSTACK_DEPTH_TYPE uxStackDepth,
                                void * const pvParameters,
                                UBaseType_t uxPriority,
                                StackType_t * const puxStackBuffer,
                                StaticTask_t * const pxTaskBuffer )
{
    TaskHandle_t xReturn = NULL;
    TCB_t * pxNewTCB;

    traceENTER_xTaskCreateStatic( pxTaskCode, pcName, uxStackDepth, pvParameters, uxPriority, puxStackBuffer, pxTaskBuffer );

    pxNewTCB = prvCreateStaticTask( pxTaskCode, pcName, uxStackDepth, pvParameters, uxPriority, puxStackBuffer, pxTaskBuffer, &xReturn );

    if( pxNewTCB != NULL )
    {
        #if ( ( configNUMBER_OF_CORES > 1 ) && ( configUSE_CORE_AFFINITY == 1 ) )
        {
            /* Set the task's affinity before scheduling it. */
            pxNewTCB->uxCoreAffinityMask = configTASK_DEFAULT_CORE_AFFINITY;
        }
        #endif

        prvAddNewTaskToReadyList( pxNewTCB );
    }
    else
    {
        mtCOVERAGE_TEST_MARKER();
    }

    traceRETURN_xTaskCreateStatic( xReturn );

    return xReturn;
}

static TCB_t * prvCreateRestrictedStaticTask( const TaskParameters_t * const pxTaskDefinition,
                                              TaskHandle_t * const pxCreatedTask )
{
    TCB_t * pxNewTCB;

    configASSERT( pxTaskDefinition->puxStackBuffer != NULL );
    configASSERT( pxTaskDefinition->pxTaskBuffer != NULL );

    if( ( pxTaskDefinition->puxStackBuffer != NULL ) && ( pxTaskDefinition->pxTaskBuffer != NULL ) )
    {
        /* Allocate space for the TCB.  Where the memory comes from depends
         * on the implementation of the port malloc function and whether or
         * not static allocation is being used. */
        pxNewTCB = ( TCB_t * ) pxTaskDefinition->pxTaskBuffer;
        ( void ) memset( ( void * ) pxNewTCB, 0x00, sizeof( TCB_t ) );

        /* Store the stack location in the TCB. */
        pxNewTCB->pxStack = pxTaskDefinition->puxStackBuffer;

        #if ( tskSTATIC_AND_DYNAMIC_ALLOCATION_POSSIBLE != 0 )
        {
            /* Tasks can be created statically or dynamically, so note this
             * task was created statically in case the task is later deleted. */
            pxNewTCB->ucStaticallyAllocated = tskSTATICALLY_ALLOCATED_STACK_AND_TCB;
        }
        #endif /* tskSTATIC_AND_DYNAMIC_ALLOCATION_POSSIBLE */

        prvInitialiseNewTask( pxTaskDefinition->pvTaskCode,
                              pxTaskDefinition->pcName,
                              pxTaskDefinition->usStackDepth,
                              pxTaskDefinition->pvParameters,
                              pxTaskDefinition->uxPriority,
                              pxCreatedTask, pxNewTCB,
                              pxTaskDefinition->xRegions );
    }
    else
    {
        pxNewTCB = NULL;
    }

    return pxNewTCB;
}

