TaskHandle_t pvTaskIncrementMutexHeldCount( void )
{
    TCB_t * pxTCB;

    traceENTER_pvTaskIncrementMutexHeldCount();

    pxTCB = pxCurrentTCB;

    /* If xSemaphoreCreateMutex() is called before any tasks have been created
     * then pxCurrentTCB will be NULL. */
    if( pxTCB != NULL )
